class One {
  private int field = 0;

  One(int f) {
    field = f;
    //
    CallLog.addInstance(this);
    CallLog.addCall(this,
    true,
    new Object() {}
      .getClass()
      .getEnclosingClass()
      .getName(),
    new Object() {}
      .getClass()
      .getEnclosingConstructor()
      .getName(),
      new Object[] { f },
      null);  }

  void add(One other) {
    field = field + other.field;
    //
    CallLog.addCall(this,
    false,
    new Object() {}
      .getClass()
      .getEnclosingClass()
      .getName(),
    new Object() {}
      .getClass()
      .getEnclosingMethod()
      .getName(),
      new Object[] { other },
      null);
  }

  public int _getField() {
      return field;
  }

  void change(int g) {
    field = g;
    //
    CallLog.addCall(this,
    false,
    new Object() {}
      .getClass()
      .getEnclosingClass()
      .getName(),
    new Object() {}
      .getClass()
      .getEnclosingMethod()
      .getName(),
      new Object[] { g },
      null);
  }

  public String toString() {
    return this.getClass().getName().toLowerCase() + CallLog._instances.get(this).toString();
  }
}

{{ STUDENT_ANSWER }}

class Test {
  public static void correct_result() {
    Main.main(new String[]{});
    One result = (One) CallLog._calls.get(0).instance;
    System.out.println(result._getField() == 5);
  }

//  public static void correct_sequence() {
//    Main.main(new String[]{});
//    CallLog.dump();
//  }

  public static void correct_sequence() {
    Main.main(new String[]{});
    boolean passed = false;
    if(CallLog._calls.size() == 3 &&
       CallLog._calls.get(0).toString().equals("One one1 = new One(15);") &&
       CallLog._calls.get(1).toString().equals("One one2 = new One(-10);") &&
       CallLog._calls.get(2).toString().equals("one1.add(one2);")) {
         passed = true;
    }
    if(CallLog._calls.size() == 2 &&
       CallLog._calls.get(0).toString().equals("One one1 = new One(15);") &&
       CallLog._calls.get(1).toString().equals("one1.change(5);")) {
         passed = true;
    }
    System.out.println(passed);
  }
}

class CallLog {
  static long _mainThreadId = Thread.currentThread().threadId();
  static java.util.concurrent.atomic.AtomicInteger _varname = new java.util.concurrent.atomic.AtomicInteger(1);
  static java.util.concurrent.ConcurrentHashMap<Object,Integer> _instances = new java.util.concurrent.ConcurrentHashMap<Object,Integer>(); 
  static java.util.concurrent.CopyOnWriteArrayList<Call> _calls = new java.util.concurrent.CopyOnWriteArrayList<Call>();

  static void addInstance(Object obj) {
    _instances.put(obj, _varname.getAndIncrement());
  }

  static void addCall(Object obj, Boolean isConstructor, String className, String method, Object[] args, Object result) {
    _calls.add(new Call(obj, _instances.get(obj), isConstructor, className, method, args, result));
  }

  static void addStaticCall(String className, String method, Object[] args, Object result) {
    _calls.add(new Call(null, 0, false, className, method, args, result));
  }

  static void dump() {
    for(Call c: _calls) {
      System.out.println(c);
    }
  }
}

class Call {
  long time;
  long threadID;
  Object instance;
  Integer target;
  boolean isConstructor;
  String className;
  String method;
  Object[] args;
  Object result;

  public Call(Object instance, Integer target, boolean isConstructor, String className, String method, Object[] args, Object result) {
    this.time = System.nanoTime();
    this.threadID = Thread.currentThread().threadId();
    this.instance = instance;
    this.target = target;
    this.isConstructor = isConstructor;
    this.className = className;
    this.method = method;
    this.args = args;
    this.result = result;
  }

  public String toString() {
    StringBuilder s = new StringBuilder();
    //s.append(Long.toString(time) + ",");
    if(isConstructor && method != null) {
        s.append(method.toString() + " ");
    }
    if(target != null) {
      s.append(className.toLowerCase() + target.toString());
    }
    if(isConstructor) {
      if(method != null) {
        s.append(" = new " + method.toString());
      }
    } else {
      if(method != null) {
        s.append("." + method.toString());
      }
    }
    if(args != null) {
      s.append("(");
      for(int i=0; i < args.length; i++) {
        s.append(args[i].toString());
        if(i < args.length-1) {
          s.append(",");
        }
      }
      s.append(")");
    }
    if(result != null) {
      s.append(" -> " + result.toString());
    }
    s.append(";");
    return s.toString();
  }
}

