    public double getAmount() {
        return amount;
    }

    public void changeReceiver(String person) {
        from = person;
    }

    public void changePayer(String person) {
        to = person;
    }

    public void addToAmount(double extra) {
        amount += extra;
    }

    public void makePayment() {

    }

}

