question.answer:
class Transaction {
    double amount;
    String from;
    String to;
    Payment money;

    public Transaction(double a, String f, String t, Payment m) {
        amount = a;
        from = f;
        to = t;
        money = m;
    }

    public double getAmount() {
        return amount;
    }

    public void changeReceiver(String person) {
        from = person;
    }

    public void changePayer(String person) {
        to = person;
    }

    public void addToAmount(double extra) {
        amount += extra;
    }

    public void makePayment() {
        money.pay(amount);
    }

}
